    if eng.sol.check() != z3.sat:
        raise EngineError('model unsat after fixing k')
    wq = eng.witness_from_model(eng.sol.model())
    _tick('witness')

    # ---- demand ranges (then propagate them into both encodings) --------
    dem_ranges = []
    ambiguous = False
    for s in range(S):
        row = []
        for c in range(C):
            blo, bhi = snaps[s]['bounds'][c]
            if blo == bhi:
                row.append([blo, bhi])
                continue
            lo, hi = eng.int_pair(s, mdl.dem_coef[c])
            lo //= K
            hi //= K
            row.append([lo, hi])
            if lo != hi:
                ambiguous = True
            eng.tighten(s, mdl.dem_coef[c], lo * K, hi * K)
        dem_ranges.append(row)
    _tick('demand ranges done (%d lp, %d int)' % (len(eng.lpcache),
                                                 len(eng.intcache)))

    # ---- link ranges ----------------------------------------------------
    link_ranges = []
    for s in range(S):
        lrow = []
        for ei in range(E):
            coef = mdl.link_coef[ei]
            lo, hi = eng.int_pair(s, coef)
            lrow.append([rat_str(lo, K), rat_str(hi, K)])
        link_ranges.append(lrow)
    _tick('link ranges done (%d lp, %d int, %d checks)' %
          (len(eng.lpcache), len(eng.intcache), eng.nchecks))

    wlinks, wfaults = eng.evaluate(wq)
    if len(wfaults) != k:
        raise EngineError('witness has %d faults, expected %d' % (len(wfaults), k))
    status = 'ambiguous' if ambiguous else 'unique'

    # ---- forced / possible faulty domains -------------------------------
    forced = []
    possible = []
    for d in mdl.observed_domains:
        fb = eng.iv.fvars[d]
        if not eng.check([z3.Not(fb)]):
            forced.append(d)
            possible.append(d)
        elif eng.check([fb]):
            possible.append(d)
    _tick('faults done')

    # ---- controller verdicts --------------------------------------------
    verdicts = []
    for s in range(S):
        ctrl = snaps[s]['controller']
        tol = snaps[s]['tolerance']
        agree = []
        for c in range(C):
            agree.append(eng.iv.q[s][c] >= ctrl[c] - tol)
            agree.append(eng.iv.q[s][c] <= ctrl[c] + tol)
        a = z3.And(agree) if agree else z3.BoolVal(True)
        yes = eng.check([a])
        no = eng.check([z3.Not(a)])
        if yes and no:
            verdicts.append('undetermined')
        elif yes:
            verdicts.append('consistent')
        else:
            verdicts.append('inconsistent')
    _tick('verdicts done')

    # ---- alternative explanation ----------------------------------------
    alt = None
    if ambiguous:
        for s in range(S):
            if alt is not None:
                break
            for c in range(C):
                lo, hi = dem_ranges[s][c]
                if lo == hi:
                    continue
                v = wq[s][c]
                cands = []
                if v < hi:
                    cands.append(eng.iv.q[s][c] >= v + 1)
                if v > lo:
                    cands.append(eng.iv.q[s][c] <= v - 1)
                for extra in cands:
                    ok, aq = eng.check_with_model([extra])
                    if not ok or aq == wq:
                        continue
                    alinks, afaults = eng.evaluate(aq)
                    if len(afaults) != k:
                        raise EngineError('alternative fault count mismatch')
                    alt = {'demands': aq,
                           'links': [[rat_str(v2, K) for v2 in row]
                                     for row in alinks],
                           'faults': afaults}
                    break
                if alt is not None:
                    break
    _tick('alternative done')

    snap_out = [{'id': snaps[s]['id'], 'demands': dem_ranges[s],
                 'links': link_ranges[s], 'verdict': verdicts[s]}
                for s in range(S)]

    return {'id': rid, 'status': status, 'min_faults': k,
            'faults': {'forced': forced, 'possible': possible},
            'snapshots': snap_out,
            'witness': {'demands': wq,
                        'links': [[rat_str(v, K) for v in row] for row in wlinks],
                        'faults': wfaults},
            'alternative': alt}


