_LINE_BUDGET = float(os.environ.get('ANALYZE_LINE_BUDGET', '45'))


def process_line(raw):
    started = time.time()
    try:
        value = json.loads(raw, parse_constant=_bad_const)
    except Exception:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    rid = None
    if isinstance(value, dict):
        cand = value.get('id')
        if is_name(cand):
            rid = cand
    try:
        inst = parse_request(value)
    except Invalid:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    except RecursionError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    try:
        return solve(inst, deadline=started + _LINE_BUDGET)
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}


